# ---------------------------------------------------------------------------
# Parser for the query language
# ---------------------------------------------------------------------------

class ParseError(Exception):
    def __init__(self, msg, pos=None, span=None):
        super().__init__(msg)
        self.msg = msg
        self.pos = pos
        self.span = span


class Lexer:
    """Simple token stream with position tracking."""
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def eof(self):
        return self.pos >= len(self.text)

    def peek(self, n=1):
        return self.text[self.pos:self.pos+n]

    def skip_ws(self):
        while self.pos < len(self.text) and self.text[self.pos] in " \t\r\n":
            self.pos += 1

    def starts_with(self, s):
        return self.text.startswith(s, self.pos)

    def consume(self, s):
        if self.starts_with(s):
            self.pos += len(s)
            return True
        return False

    def read_quoted_string(self):
        # Already positioned at opening quote
        if self.text[self.pos] != '"':
            raise ParseError("expected '\"'", self.pos)
        start = self.pos
        self.pos += 1
        out = []
        while self.pos < len(self.text):
            c = self.text[self.pos]
            if c == '\\' and self.pos + 1 < len(self.text):
                nxt = self.text[self.pos+1]
                if nxt == '"':
                    out.append('"'); self.pos += 2; continue
                if nxt == '\\':
                    out.append('\\'); self.pos += 2; continue
                if nxt == 'n':
                    out.append('\n'); self.pos += 2; continue
                if nxt == 't':
                    out.append('\t'); self.pos += 2; continue
                out.append(nxt); self.pos += 2; continue
            if c == '"':
                self.pos += 1
                return ''.join(out)
            out.append(c); self.pos += 1
        raise ParseError("unterminated string", start)

    def read_number(self):
        start = self.pos
        if self.text[self.pos] == '-':
            self.pos += 1
        while self.pos < len(self.text) and self.text[self.pos].isdigit():
            self.pos += 1
        is_float = False
        if self.pos < len(self.text) and self.text[self.pos] == '.':
            is_float = True
            self.pos += 1
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self.pos += 1
        if self.pos < len(self.text) and self.text[self.pos] in "eE":
            is_float = True
            self.pos += 1
            if self.pos < len(self.text) and self.text[self.pos] in "+-":
                self.pos += 1
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self.pos += 1
        tok = self.text[start:self.pos]
        if tok in ("", "-"):
            raise ParseError("expected number", start)
        return float(tok) if is_float else int(tok)

    def read_ident(self):
        start = self.pos
        while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'):
            self.pos += 1
        return self.text[start:self.pos]


