# --- Query language parser ---------------------------------------------------

OPERATORS = {
    "json", "logfmt", "parse", "fields", "where", "limit", "split",
    "count", "sum", "min", "max", "average", "avg", "total", "sort",
    "count_distinct", "timeslice",
}

def parse_query(text):
    text = text.strip()
    if text == "":
        return Query(Filter('all'), [])
    # Split filter vs pipeline on first unprotected '|'
    parts = split_top(text, '|')
    flt = parse_filter(parts[0].strip()) if parts[0].strip() else Filter('all')
    ops = []
    for part in parts[1:]:
        seg = part.strip()
        if seg == "":
            raise ParseError("expecting an expression", pos=None, span=(len(text), len(text)))
        ops.extend(parse_operator_chain(seg))
    return Query(flt, ops)


def split_top(text, sep):
    """Split string by `sep` ignoring anything inside quotes or parens."""
    out = []
    cur = []
    depth = 0
    i = 0
    while i < len(text):
        c = text[i]
        if c == '"':
            j = i + 1
            while j < len(text):
                if text[j] == '\\' and j + 1 < len(text):
                    j += 2
                    continue
                if text[j] == '"':
                    break
                j += 1
            cur.append(text[i:j+1])
            i = j + 1
            continue
        if c == '(':
            depth += 1
            cur.append(c); i += 1; continue
        if c == ')':
            depth -= 1
            cur.append(c); i += 1; continue
        if depth == 0 and c == sep:
            out.append(''.join(cur))
            cur = []
            i += 1
            continue
        cur.append(c); i += 1
    out.append(''.join(cur))
    return out


def parse_filter(text):
    # Simple recursive descent for AND/OR/NOT and atoms
    lx = Lexer(text)
    lx.skip_ws()
    tree = parse_filter_or(lx)
    lx.skip_ws()
    if not lx.eof():
        raise ParseError("unexpected characters in filter", lx.pos)
    return tree


def parse_filter_or(lx):
    left = parse_filter_and(lx)
    while True:
        lx.skip_ws()
        save = lx.pos
        if lx.starts_with("OR") and (lx.pos + 2 == len(lx.text) or lx.text[lx.pos+2] in " \t("):
            lx.pos += 2
            right = parse_filter_and(lx)
            if left.kind == 'or':
                left.children.append(right)
            else:
                left = Filter('or', children=[left, right])
            continue
        lx.pos = save
        break
    return left


def parse_filter_and(lx):
    left = parse_filter_not(lx)
    while True:
        lx.skip_ws()
        save = lx.pos
        if lx.starts_with("AND") and (lx.pos + 3 == len(lx.text) or lx.text[lx.pos+3] in " \t("):
            lx.pos += 3
            right = parse_filter_not(lx)
            if left.kind == 'and':
                left.children.append(right)
            else:
                left = Filter('and', children=[left, right])
            continue
        # Implicit AND: next token that is not end/)/OR/AND
        if lx.eof() or lx.text[lx.pos] == ')':
            break
        # Try to parse another atom and combine
        try:
            right = parse_filter_not(lx)
        except ParseError:
            lx.pos = save
            break
        if left.kind == 'and':
            left.children.append(right)
        else:
            left = Filter('and', children=[left, right])
    return left


def parse_filter_not(lx):
    lx.skip_ws()
    if lx.starts_with("NOT") and (lx.pos + 3 == len(lx.text) or lx.text[lx.pos+3] in " \t("):
        lx.pos += 3
        child = parse_filter_atom(lx)
        return Filter('not', child=child)
    return parse_filter_atom(lx)


def parse_filter_atom(lx):
    lx.skip_ws()
    if lx.eof():
        raise ParseError("expected filter", lx.pos)
    c = lx.text[lx.pos]
    if c == '(':
        lx.pos += 1
        node = parse_filter_or(lx)
        lx.skip_ws()
        if not lx.consume(')'):
            raise ParseError("expected ')'", lx.pos)
        return node
    if c == '"':
        s = lx.read_quoted_string()
        return Filter('quoted', text=s)
    if c == '*' and (lx.pos + 1 == len(lx.text) or lx.text[lx.pos+1] in " \t|)"):
        # Bare '*' means match everything
        lx.pos += 1
        return Filter('all')
    # Otherwise, read a word (may contain wildcards)
    start = lx.pos
    while lx.pos < len(lx.text) and lx.text[lx.pos] not in " \t()|":
        lx.pos += 1
    word = lx.text[start:lx.pos]
    if word == "":
        raise ParseError("expected filter", lx.pos)
    # AND/OR/NOT shouldn't be read as words at this level because they are keywords
    if word in ("AND", "OR", "NOT"):
        raise ParseError(f"unexpected {word}", start)
    return Filter('word', text=word)
