def parse_operator_chain(text):
    """Operator segment can be comma-separated aggregates, or a single non-agg op."""
    # If it's a known non-aggregate operator, handle it directly.
    lx = Lexer(text)
    lx.skip_ws()
    name_start = lx.pos
    ident = lx.read_ident()
    lx.skip_ws()
    rest = text[lx.pos:].strip()

    # Non-aggregate operators
    if ident == "json":
        return [OpJson(from_field=parse_from(rest))]
    if ident == "logfmt":
        return [OpLogfmt(from_field=parse_from(rest))]
    if ident == "fields":
        return [parse_fields_op(rest)]
    if ident == "where":
        return [OpWhere(parse_expression(rest))]
    if ident == "limit":
        if rest == "":
            raise ParseError("limit requires a value", lx.pos)
        try:
            n = int(rest)
        except ValueError:
            raise ParseError("limit expects integer", lx.pos)
        return [OpLimit(n)]
    if ident == "parse":
        return [parse_parse_op(rest, regex=False)]
    if ident == "parse" and False:
        pass
    if ident == "split":
        return [parse_split_op(rest, raw_inside=None)]
    if ident == "timeslice":
        return [parse_timeslice_op(rest)]
    if ident == "sort":
        return [parse_sort_op(rest)]

    # "parse regex ..."
    if ident == "parse":
        pass

    # Expression-as-field: "<expr> as <name>"
    # Aggregate operators may be comma-separated.
    if ident in ("count", "sum", "min", "max", "average", "avg",
                 "total", "count_distinct") or re.fullmatch(r"p\d+(\.\d+)?|pct\d+", ident or ""):
        return [parse_aggregate_chain(text)]

    # Handle "parse regex" specially (keyword after 'parse')
    if ident == "":
        raise ParseError("expecting an expression", lx.pos)

    # Treat as expression-as-field (e.g. "a + b as sum")
    try:
        return [parse_expr_as_op(text)]
    except ParseError:
        # Known-operator? Otherwise unknown operator error.
        suggestion = suggest_operator(ident)
        raise OperatorError(ident, name_start, suggestion)


def suggest_operator(name):
    # Levenshtein-ish suggestion
    best = None; best_d = 3
    for op in OPERATORS:
        d = edit_distance(op, name)
        if d < best_d:
            best_d = d; best = op
    return best


def edit_distance(a, b):
    la, lb = len(a), len(b)
    if la == 0: return lb
    if lb == 0: return la
    prev = list(range(lb + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            ins = cur[-1] + 1
            dele = prev[j] + 1
            sub = prev[j-1] + (ca != cb)
            cur.append(min(ins, dele, sub))
        prev = cur
    return prev[-1]


class OperatorError(ParseError):
    def __init__(self, op_name, pos, suggestion=None):
        super().__init__(f"Expected an operator at position {pos}", pos)
        self.op_name = op_name
        self.op_pos = pos
        self.suggestion = suggestion
