# ---- Parsing helpers for operators -----------------------------------------

def parse_from(text):
    text = text.strip()
    if text == "":
        return None
    m = re.match(r"from\s+(\S+)$", text)
    if m:
        return m.group(1)
    return None


def parse_fields_op(text):
    text = text.strip()
    mode = 'only'  # default
    if text.startswith('+'):
        mode = 'only'; text = text[1:].strip()
    elif text.startswith('-'):
        mode = 'except'; text = text[1:].strip()
    elif text.startswith("only"):
        mode = 'only'; text = text[4:].strip()
    elif text.startswith("except"):
        mode = 'except'; text = text[6:].strip()
    fields = [s.strip() for s in text.split(",") if s.strip()]
    return OpFields(mode, fields)


def parse_parse_op(text, regex=False):
    # may start with "regex"
    t = text.strip()
    is_regex = False
    if t.startswith("regex"):
        is_regex = True
        t = t[5:].strip()
    # Pattern string
    lx = Lexer(t)
    lx.skip_ws()
    if lx.eof() or lx.text[lx.pos] != '"':
        raise ParseError("expected pattern string", lx.pos)
    pat = lx.read_quoted_string()
    rest = lx.text[lx.pos:].strip()
    # optional "from field"
    from_field = None
    m = re.match(r"from\s+(\S+)\b", rest)
    if m:
        from_field = m.group(1)
        rest = rest[m.end():].strip()
    # optional "as name1, name2, ..."
    as_names = []
