# ---- Expression parser ------------------------------------------------------

class Expr:
    def __init__(self, kind, **kw):
        self.kind = kind
        self.__dict__.update(kw)


def parse_expression(text):
    lx = Lexer(text)
    lx.skip_ws()
    e = parse_or_expr(lx)
    lx.skip_ws()
    if not lx.eof():
        raise ParseError("expected end of expression", lx.pos)
    return e


def parse_or_expr(lx):
    left = parse_and_expr(lx)
    while True:
        lx.skip_ws()
        if lx.starts_with("||") or match_kw(lx, "or"):
            if lx.starts_with("||"):
                lx.pos += 2
            else:
                lx.pos += 2
            right = parse_and_expr(lx)
            left = Expr('or', left=left, right=right)
            continue
        break
    return left


def parse_and_expr(lx):
    left = parse_cmp_expr(lx)
    while True:
        lx.skip_ws()
        if lx.starts_with("&&"):
            lx.pos += 2
            right = parse_cmp_expr(lx)
            left = Expr('and', left=left, right=right)
            continue
        if match_kw(lx, "and"):
            lx.pos += 3
            right = parse_cmp_expr(lx)
            left = Expr('and', left=left, right=right)
            continue
        break
    return left


def match_kw(lx, kw):
    if lx.starts_with(kw):
        nxt = lx.pos + len(kw)
        if nxt >= len(lx.text) or not (lx.text[nxt].isalnum() or lx.text[nxt] == '_'):
            return True
    return False


def parse_cmp_expr(lx):
    left = parse_add_expr(lx)
    lx.skip_ws()
    for op in ("==", "!=", "<>", ">=", "<=", ">", "<"):
        if lx.starts_with(op):
            lx.pos += len(op)
            right = parse_add_expr(lx)
            canonical = "!=" if op == "<>" else op
            return Expr('cmp', op=canonical, left=left, right=right)
    return left


def parse_add_expr(lx):
    left = parse_mul_expr(lx)
    while True:
        lx.skip_ws()
        if lx.pos < len(lx.text) and lx.text[lx.pos] in "+-":
            op = lx.text[lx.pos]; lx.pos += 1
            right = parse_mul_expr(lx)
            left = Expr('binop', op=op, left=left, right=right)
        else:
            break
    return left


def parse_mul_expr(lx):
    left = parse_unary(lx)
    while True:
        lx.skip_ws()
        if lx.pos < len(lx.text) and lx.text[lx.pos] in "*/":
            op = lx.text[lx.pos]; lx.pos += 1
            right = parse_unary(lx)
            left = Expr('binop', op=op, left=left, right=right)
        else:
            break
    return left


def parse_unary(lx):
    lx.skip_ws()
    if lx.pos < len(lx.text) and lx.text[lx.pos] == '!':
        lx.pos += 1
        return Expr('not', child=parse_unary(lx))
    if lx.pos < len(lx.text) and lx.text[lx.pos] == '-':
        # Could be unary minus - but only if not a number context; treat always as negation of sub expr
        save = lx.pos
        lx.pos += 1
        # try number first
        if lx.pos < len(lx.text) and (lx.text[lx.pos].isdigit() or lx.text[lx.pos] == '.'):
            lx.pos = save
            n = lx.read_number()
            return Expr('num', value=n)
        child = parse_unary(lx)
        return Expr('neg', child=child)
    return parse_primary(lx)


def parse_primary(lx):
    lx.skip_ws()
    if lx.eof():
        raise ParseError("expecting an expression", lx.pos, (lx.pos, lx.pos))
    c = lx.text[lx.pos]
    if c == '(':
        lx.pos += 1
        e = parse_or_expr(lx)
        lx.skip_ws()
        if not lx.consume(')'):
            raise ParseError("expected )", lx.pos)
        return e
    if c == '"':
        s = lx.read_quoted_string()
        return Expr('str', value=s)
    if c.isdigit() or (c == '.' and lx.pos + 1 < len(lx.text) and lx.text[lx.pos+1].isdigit()):
        n = lx.read_number()
        return Expr('num', value=n)
    if c == '[' and lx.pos + 1 < len(lx.text) and lx.text[lx.pos+1] == '"':
        # Escaped field name: ["foo bar"]
        lx.pos += 1
        s = lx.read_quoted_string()
        if not lx.consume(']'):
            raise ParseError("expected ]", lx.pos)
        return parse_field_accessors(lx, Expr('field', name=s))
    # Identifier or function call
    start = lx.pos
    ident = lx.read_ident()
    if not ident:
        raise ParseError("expecting an expression", lx.pos, (lx.pos, lx.pos))
    if ident == "true":
        return Expr('bool', value=True)
    if ident == "false":
        return Expr('bool', value=False)
    if ident == "null" or ident == "None":
        return Expr('null')
    lx.skip_ws()
    if lx.pos < len(lx.text) and lx.text[lx.pos] == '(':
        # Function call
        lx.pos += 1
        args = []
        lx.skip_ws()
        if lx.pos < len(lx.text) and lx.text[lx.pos] != ')':
            args.append(parse_or_expr(lx))
            while True:
                lx.skip_ws()
                if lx.consume(','):
                    args.append(parse_or_expr(lx))
                else:
                    break
        lx.skip_ws()
        if not lx.consume(')'):
            raise ParseError("expected )", lx.pos)
        return Expr('call', name=ident, args=args)
    return parse_field_accessors(lx, Expr('field', name=ident))


def parse_field_accessors(lx, base):
    while True:
        lx.skip_ws()
        if lx.pos < len(lx.text) and lx.text[lx.pos] == '.':
            lx.pos += 1
            # dotted path: field name after dot
            if lx.pos < len(lx.text) and lx.text[lx.pos].isalpha():
                name = lx.read_ident()
                base = Expr('member', target=base, name=name)
                continue
            raise ParseError("expected field name after '.'", lx.pos)
        if lx.pos < len(lx.text) and lx.text[lx.pos] == '[':
            lx.pos += 1
            idx_expr = parse_or_expr(lx)
            lx.skip_ws()
            if not lx.consume(']'):
                raise ParseError("expected ]", lx.pos)
            base = Expr('index', target=base, index=idx_expr)
            continue
        break
    return base
