# ---- Aggregates parsing ------------------------------------------------------

def parse_aggregate_chain(text):
    """Parse e.g. 'count, sum(a) as tot by b, c' into an AggChain op."""
    # Find trailing 'by <key_exprs>'
    # Must find last top-level 'by' keyword
    by_pos = find_top_kw(text, 'by')
    if by_pos is not None:
        agg_part = text[:by_pos].strip()
        key_part = text[by_pos+2:].strip()
    else:
        agg_part = text.strip()
        key_part = ""
    aggs = []
    for item in split_top(agg_part, ','):
        item = item.strip()
        if not item:
            continue
        aggs.append(parse_single_agg(item))
    keys = []
    if key_part:
        for k in split_top(key_part, ','):
            k = k.strip()
            if not k:
                continue
            # Each key is either a name or expression
            expr = parse_expression(k)
            name = key_name_for(expr, k)
            keys.append((name, expr))
    return OpAggregate(aggs, keys)


def key_name_for(expr, src):
    """Pick a column name for a by-key expression."""
    if expr.kind == 'field':
        return expr.name
    return src.strip()


def find_top_kw(text, kw):
    """Find last occurrence of `kw` outside quotes/parens."""
    lx = Lexer(text)
    last = None
    while lx.pos < len(lx.text):
        c = lx.text[lx.pos]
        if c == '"':
            lx.read_quoted_string(); continue
        if c == '(':
            depth = 1; lx.pos += 1
            while lx.pos < len(lx.text) and depth > 0:
                if lx.text[lx.pos] == '"':
                    lx.read_quoted_string(); continue
                if lx.text[lx.pos] == '(':
                    depth += 1
                elif lx.text[lx.pos] == ')':
                    depth -= 1
                lx.pos += 1
            continue
        if lx.starts_with(kw):
            before_ok = lx.pos == 0 or not (lx.text[lx.pos-1].isalnum() or lx.text[lx.pos-1] == '_')
            after = lx.pos + len(kw)
            after_ok = after >= len(lx.text) or not (lx.text[after].isalnum() or lx.text[after] == '_')
            if before_ok and after_ok:
                last = lx.pos
                lx.pos = after
                continue
        lx.pos += 1
    return last


def parse_single_agg(item):
    # item like: name, name(expr), name(expr) as X, pNN(expr)
    lx = Lexer(item)
    lx.skip_ws()
    start = lx.pos
    ident = lx.read_ident()
    if not ident:
        raise ParseError("expected aggregate", lx.pos)
    lx.skip_ws()
    inner = None
    if lx.pos < len(lx.text) and lx.text[lx.pos] == '(':
        lx.pos += 1
        lx.skip_ws()
        if lx.pos < len(lx.text) and lx.text[lx.pos] != ')':
            inner = parse_or_expr(lx)
        lx.skip_ws()
        if not lx.consume(')'):
            raise ParseError("expected )", lx.pos)
    lx.skip_ws()
    as_name = None
    if lx.starts_with("as"):
        lx.pos += 2
        lx.skip_ws()
        name_start = lx.pos
        while lx.pos < len(lx.text) and (lx.text[lx.pos].isalnum() or lx.text[lx.pos] == '_'):
            lx.pos += 1
        as_name = lx.text[name_start:lx.pos]
    # Build aggregator descriptor
    if ident == "count":
        return Agg('count', inner, as_name or "_count")
    if ident == "sum":
        return Agg('sum', inner, as_name or "_sum")
    if ident == "min":
        return Agg('min', inner, as_name or "_min")
    if ident == "max":
        return Agg('max', inner, as_name or "_max")
    if ident in ("average", "avg"):
        return Agg('average', inner, as_name or "_average")
    if ident == "total":
        return Agg('total', inner, as_name or "_total")
    if ident == "count_distinct":
        return Agg('count_distinct', inner, as_name or "_countDistinct")
    m = re.fullmatch(r'p(\d+(?:\.\d+)?)', ident)
    if not m:
        m = re.fullmatch(r'pct(\d+(?:\.\d+)?)', ident)
    if m:
        pct = float(m.group(1))
        default = f"p{m.group(1)}"
        return Agg('percentile', inner, as_name or default, pct=pct)
    raise ParseError(f"unknown aggregate {ident}", start)


class Agg:
    def __init__(self, kind, expr, out_name, pct=None):
        self.kind = kind
        self.expr = expr
        self.out_name = out_name
        self.pct = pct


def parse_expr_as_op(text):
    # "<expr> as <name>"
    m = re.search(r'\bas\s+(\S+)\s*$', text)
    if not m:
        raise ParseError("expression must end with 'as <name>'", 0)
    name = m.group(1)
    expr = parse_expression(text[:m.start()].strip())
    return OpExprAs(expr, name)
