# ---------------------------------------------------------------------------
# Expression evaluation
# ---------------------------------------------------------------------------

def eval_expr(expr, row):
    k = expr.kind
    if k == 'num': return expr.value
    if k == 'str': return expr.value
    if k == 'bool': return expr.value
    if k == 'null': return NULL
    if k == 'field':
        return row.get(expr.name, NULL)
    if k == 'member':
        base = eval_expr(expr.target, row)
        if isinstance(base, dict):
            return base.get(expr.name, NULL)
        return NULL
    if k == 'index':
        base = eval_expr(expr.target, row)
        idx = eval_expr(expr.index, row)
        if isinstance(idx, (int, float)):
            idx = int(idx)
            if isinstance(base, list):
                if -len(base) <= idx < len(base):
                    return base[idx]
                return NULL
            if isinstance(base, str):
                if -len(base) <= idx < len(base):
                    return base[idx]
                return NULL
        if isinstance(idx, str):
            if isinstance(base, dict):
                return base.get(idx, NULL)
        return NULL
    if k == 'neg':
        v = eval_expr(expr.child, row)
        n = to_number(v)
        return -n if n is not None else NULL
    if k == 'not':
        v = eval_expr(expr.child, row)
        return not truthy(v)
    if k == 'and':
        return truthy(eval_expr(expr.left, row)) and truthy(eval_expr(expr.right, row))
    if k == 'or':
        a = eval_expr(expr.left, row)
        if truthy(a): return True
        return truthy(eval_expr(expr.right, row))
    if k == 'cmp':
        return eval_cmp(expr.op, eval_expr(expr.left, row), eval_expr(expr.right, row))
    if k == 'binop':
        a = eval_expr(expr.left, row)
        b = eval_expr(expr.right, row)
        an = to_number(a); bn = to_number(b)
        if an is None or bn is None:
            return NULL
        if expr.op == '+': return an + bn
        if expr.op == '-': return an - bn
        if expr.op == '*': return an * bn
        if expr.op == '/':
            if bn == 0:
                return NULL
            return an / bn
    if k == 'call':
        return eval_call(expr.name, [eval_expr(a, row) for a in expr.args], row)
    raise RuntimeError(f"unknown expr kind {k}")


def truthy(v):
    if isinstance(v, Null) or v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, (int, float)): return v != 0
    if isinstance(v, str): return v != ""
    if isinstance(v, (list, dict)): return len(v) > 0
    return True


def eval_cmp(op, a, b):
    # Null handling: None == None
    a_null = isinstance(a, Null)
    b_null = isinstance(b, Null)
    if a_null and b_null:
        return op in ("==", "<=", ">=")
    if a_null or b_null:
        return op == "!="
    # If both numeric-like, compare as numbers
    an = to_number(a) if not isinstance(a, bool) else None
    bn = to_number(b) if not isinstance(b, bool) else None
    if an is not None and bn is not None:
        x, y = an, bn
    else:
        x, y = a, b
    try:
        if op == "==": return x == y
        if op == "!=": return x != y
        if op == "<": return x < y
        if op == "<=": return x <= y
        if op == ">": return x > y
        if op == ">=": return x >= y
    except TypeError:
        return False
    return False


def eval_call(name, args, row):
    if name == 'concat':
        return "".join(format_scalar_plain(a) for a in args)
    if name == 'length':
        a = args[0] if args else NULL
        if isinstance(a, str): return len(a)
        if isinstance(a, (list, dict)): return len(a)
        return NULL
    if name == 'toUpperCase':
        return args[0].upper() if isinstance(args[0], str) else NULL
    if name == 'toLowerCase':
        return args[0].lower() if isinstance(args[0], str) else NULL
    if name == 'substring':
        s = args[0]
        if not isinstance(s, str): return NULL
        start = int(to_number(args[1]) or 0)
        if len(args) >= 3:
            end = int(to_number(args[2]) or len(s))
            return s[start:end]
        return s[start:]
    if name == 'num':
        n = to_number(args[0])
        return n if n is not None else NULL
    if name == 'parseHex':
        s = args[0]
        if not isinstance(s, str): return NULL
        try:
            return int(s, 16)
        except ValueError:
            return NULL
    if name == 'isNull':
        return isinstance(args[0], Null)
    if name == 'isEmpty':
        v = args[0]
        if isinstance(v, Null): return True
        if isinstance(v, str): return v == ""
        return False
    if name == 'isBlank':
        v = args[0]
        if isinstance(v, Null): return True
        if isinstance(v, str): return v.strip() == ""
        return False
    if name == 'isNumeric':
        v = args[0]
        if isinstance(v, str):
            return to_number(v) is not None
        return False
    if name == 'contains':
        h, n = args[0], args[1]
        if isinstance(h, str) and isinstance(n, str):
            return n in h
        if isinstance(h, list):
            return n in h
        return False
    if name == 'if':
        cond = args[0]
        return args[1] if truthy(cond) else args[2]
    if name == 'abs':
        n = to_number(args[0]); return abs(n) if n is not None else NULL
    if name == 'now':
        return 0  # placeholder
    mathfns = {
        'acos': math.acos, 'asin': math.asin, 'atan': math.atan,
        'cbrt': lambda x: math.copysign(abs(x)**(1/3), x),
        'ceil': math.ceil, 'cos': math.cos, 'cosh': math.cosh,
        'exp': math.exp, 'expm1': math.expm1, 'floor': math.floor,
        'log': math.log, 'log10': math.log10, 'log1p': math.log1p,
        'round': lambda x: int(round(x)), 'sin': math.sin,
        'sinh': math.sinh, 'sqrt': math.sqrt, 'tan': math.tan,
        'tanh': math.tanh,
        'toDegrees': math.degrees, 'toRadians': math.radians,
    }
    if name in mathfns:
        n = to_number(args[0])
        try:
            return mathfns[name](n) if n is not None else NULL
        except Exception:
            return NULL
    if name == 'atan2':
        a = to_number(args[0]); b = to_number(args[1])
        if a is None or b is None: return NULL
        return math.atan2(a, b)
    if name == 'hypot':
        a = to_number(args[0]); b = to_number(args[1])
        if a is None or b is None: return NULL
        return math.hypot(a, b)
    return NULL
