# ---------------------------------------------------------------------------
# Operator implementations
# ---------------------------------------------------------------------------

class Operator:
    is_aggregate = False
    def process(self, row):
        return [row]
    def finish(self):
        return []


class OpJson(Operator):
    def __init__(self, from_field=None):
        self.from_field = from_field

    def process(self, row):
        if self.from_field:
            val = row.get(self.from_field)
            if not isinstance(val, str):
                sys.stderr.write(f"error: Expected JSON, found {format_scalar_plain(val)}\n")
                return []
            src = val
        else:
            src = row.get('_raw')
            if src is None:
                return [row]
        try:
            data = pyjson.loads(src)
        except Exception:
            sys.stderr.write(f"error: Expected JSON, found {src}\n")
            return []
        if not isinstance(data, dict):
            sys.stderr.write(f"error: Expected JSON, found {src}\n")
            return []
        new = dict(row)
        new.pop('_raw', None)
        for k, v in data.items():
            new[k] = jsonify(v)
        return [new]


def jsonify(v):
    if v is None:
        return NULL
    if isinstance(v, list):
        return [jsonify(x) for x in v]
    if isinstance(v, dict):
        return {k: jsonify(val) for k, val in v.items()}
    return v


class OpLogfmt(Operator):
    def __init__(self, from_field=None):
        self.from_field = from_field

    def process(self, row):
        if self.from_field:
            src = row.get(self.from_field)
            if not isinstance(src, str):
                return []
        else:
            src = row.get('_raw', "")
        parsed = parse_logfmt_line(src)
        if not parsed:
            return []
        new = dict(row)
        new.pop('_raw', None)
        new.update(parsed)
        return [new]


def parse_logfmt_line(text):
    out = {}
    i = 0
    n = len(text)
    while i < n:
        while i < n and text[i] in " \t":
            i += 1
        if i >= n: break
        # key
        ks = i
        while i < n and text[i] != '=' and text[i] not in " \t":
            i += 1
        key = text[ks:i]
        if key == "":
            i += 1
            continue
        if i >= n or text[i] != '=':
            out[key] = True
            continue
        i += 1  # skip '='
        # value
        if i < n and text[i] == '"':
            # quoted
            i += 1
            buf = []
            while i < n:
                c = text[i]
                if c == '\\' and i + 1 < n:
                    buf.append(text[i+1]); i += 2; continue
                if c == '"':
                    i += 1; break
                buf.append(c); i += 1
            out[key] = "".join(buf)
        else:
            vs = i
            while i < n and text[i] not in " \t":
                i += 1
            raw = text[vs:i]
            n_ = to_number(raw)
            out[key] = n_ if n_ is not None else raw
    return out


class OpFields(Operator):
    def __init__(self, mode, names):
        self.mode = mode
        self.names = names
    def process(self, row):
        if self.mode == 'only':
            return [{k: row[k] for k in self.names if k in row}]
        # except
        return [{k: v for k, v in row.items() if k not in self.names}]


class OpWhere(Operator):
    def __init__(self, expr):
        self.expr = expr
    def process(self, row):
        if truthy(eval_expr(self.expr, row)):
            return [row]
        return []


class OpLimit(Operator):
    def __init__(self, n):
        self.n = n
        self.buf = []
    def process(self, row):
        if self.n >= 0:
            if len(self.buf) < self.n:
                self.buf.append(row)
                return [row]
            return []
        self.buf.append(row)
        return []
    def finish(self):
        if self.n >= 0:
            return []
        if self.n == 0:
            return []
        return self.buf[self.n:]


class OpExprAs(Operator):
    def __init__(self, expr, name):
        self.expr = expr
        self.name = name
    def process(self, row):
        new = dict(row)
        new[self.name] = eval_expr(self.expr, row)
        return [new]
