class OpParse(Operator):
    def __init__(self, pattern, names, from_field, nodrop, noconvert, is_regex):
        self.pattern = pattern
        self.names = names
        self.from_field = from_field
        self.nodrop = nodrop
        self.noconvert = noconvert
        self.is_regex = is_regex
        if is_regex:
            self.regex = re.compile(pattern)
        else:
            # Build regex: literal text, '*' -> '(.*)', whitespace -> '\s+'
            out = []
            for c in pattern:
                if c == '*':
                    out.append('(.*?)')
                elif c in ' \t':
                    out.append(r'\s+')
                else:
                    out.append(re.escape(c))
            # '*' is greedy to right - use non-greedy but anchor nothing
            self.regex = re.compile(''.join(out))

    def process(self, row):
        src = row.get(self.from_field) if self.from_field else row.get('_raw', "")
        if not isinstance(src, str):
            src = "" if src is None or isinstance(src, Null) else str(src)
        m = self.regex.search(src)
        if not m:
            if self.nodrop:
                new = dict(row)
                for nm in self.names:
                    new[nm] = NULL
                if self.is_regex:
                    for nm in self.regex.groupindex:
                        new[nm] = NULL
                return [new]
            return []
        new = dict(row)
        if self.is_regex:
            for name, idx in self.regex.groupindex.items():
                v = m.group(idx)
                new[name] = self._convert(v) if not self.noconvert else v
        else:
            groups = m.groups()
            for i, nm in enumerate(self.names):
                if i < len(groups):
                    v = groups[i]
                    new[nm] = self._convert(v) if not self.noconvert else v
        return [new]

    def _convert(self, s):
        if s is None: return NULL
        n = to_number(s)
        return n if n is not None else s


class OpSplit(Operator):
    def __init__(self, input_field, sep, as_name):
        self.input_field = input_field
        self.sep = sep
        self.as_name = as_name

    def process(self, row):
        if self.input_field:
            src = row.get(self.input_field, "")
        else:
            src = row.get('_raw', "")
        if not isinstance(src, str):
            return [row]
        pieces = src.split(self.sep)
        # convert numeric-looking pieces to numbers
        vals = []
        for p in pieces:
            n = to_number(p)
            vals.append(n if n is not None else p)
        new = dict(row)
        if self.input_field and not self.as_name:
            new[self.input_field] = vals
        else:
            new[self.as_name] = vals
        return [new]


