# ---------------------------------------------------------------------------
# Driver
# ---------------------------------------------------------------------------

def parse_cli_args(argv):
    args = {'query': None, 'file': None, 'output': None, 'format': None,
            'alias_dir': None, 'no_alias': False}
    i = 0
    positional = []
    while i < len(argv):
        a = argv[i]
        if a in ('-h', '--help'):
            print_help(long=(a == '--help'))
            sys.exit(0)
        if a in ('-V', '--version'):
            print("ag 0.19.6")
            sys.exit(0)
        if a == '--no-alias':
            args['no_alias'] = True; i += 1; continue
        if a in ('-f', '--file'):
            args['file'] = argv[i+1]; i += 2; continue
        if a.startswith('--file='):
            args['file'] = a[7:]; i += 1; continue
        if a in ('-o', '--output'):
            args['output'] = argv[i+1]; i += 2; continue
        if a.startswith('--output='):
            args['output'] = a[9:]; i += 1; continue
        if a in ('-m', '--format'):
