def format_parse_error_location(query, pos, span=None):
    """Emit an error message similar to the original executable."""
    lines = query.split('\n')
    # locate line/col from pos
    if pos is None:
        pos = len(query)
    total = 0
    ln = 0
    for idx, line in enumerate(lines):
        if total + len(line) >= pos:
            ln = idx
            col = pos - total
            break
        total += len(line) + 1
    else:
        ln = len(lines) - 1
        col = len(lines[-1])
    return ln, col


def emit_parse_error(err, query):
    # best-effort: emit a spanned pointer
    if isinstance(err, OperatorError):
        op = err.op_name
        pos = err.op_pos
        sys.stderr.write("error: Expected an operator\n")
        sys.stderr.write("  |\n")
        sys.stderr.write(f"1 | {query}\n")
        sys.stderr.write(f"  | {' ' * pos}{'^' * max(1, len(op))}\n")
        sys.stderr.write("  |\n")
        sys.stderr.write(f"  = help: {op} is not a valid operator\n")
        if err.suggestion:
            sys.stderr.write(f'  = help: Did you mean "{err.suggestion}"?\n')
    else:
        msg = err.msg
        pos = err.pos if err.pos is not None else len(query)
        sys.stderr.write(f"error: {msg}\n")
        sys.stderr.write("  |\n")
        sys.stderr.write(f"1 | {query}\n")
        sys.stderr.write(f"  | {' ' * pos}^\n")
        sys.stderr.write("  |\n")
    sys.stderr.write("Error: Failed to parse query\n")


