    agg_columns = None
    if has_agg:
        for op in operators:
            if isinstance(op, OpAggregate):
                agg_columns = [name for name, _ in op.keys] + [a.out_name for a in op.aggs]
        # Apply any fields op after aggregation
        after_agg = False
        for op in operators:
            if isinstance(op, OpAggregate):
                after_agg = True
                continue
            if after_agg and isinstance(op, OpFields):
                if op.mode == 'only':
                    agg_columns = [c for c in op.names]
                else:
                    agg_columns = [c for c in (agg_columns or []) if c not in op.names]'''
s = s.replace(old, new)
open(path, 'w').write(s)
