# Test BrokenPipe more robustly by handling it silently
python3 << 'EOF'
path = "src/agrind.py"
s = open(path).read()
# Ensure we suppress broken pipe on stdout
old = '''if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        sys.exit(0)'''
new = '''if __name__ == '__main__':
    try:
        import signal
        signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    except Exception:
        pass
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        try:
            sys.stderr.close()
        except Exception:
            pass
        sys.exit(0)'''
s = s.replace(old, new)
open(path, 'w').write(s)
EOF
